public int CountDigitsRecursive(int n)
{
    if (n == 0) return 0;
    return 1 + CountDigitsRecursive(n / 10);
}

public int CountDigitsIterative(int n)
{
    if (n == 0) return 1;
    int count = 0;
    while (n > 0)
    {
        count++;
        n /= 10;
    }
    return count;
}

public int CountDigitsString(int n)
{
    return n.ToString().Length;
}
